void match_sell(Order& in) {                       // in.side == Sell
    while (in.qty > 0 && !bids.empty() && bids.begin()->first >= in.price) {
        auto lvl = bids.begin();                   // best (highest) bid level
        Order& rest = lvl->second.front();         // earliest order at that price
        Qty q = std::min(in.qty, rest.qty);
        report_trade(rest.id, in.id, lvl->first, q);   // trade at the resting price
        in.qty  -= q;
        rest.qty -= q;
        if (rest.qty == 0) { index.erase(rest.id); lvl->second.pop_front(); }
        if (lvl->second.empty()) bids.erase(lvl);  // level gone, next best becomes begin()
    }
    if (in.qty > 0) add_resting_ask(in);           // remainder rests on the ask side
}
```
